177	    /**
178	     * Generic request method mirroring SquareApiClient::request().
179	     *
180	     * @param  array<string, string|int|float|bool|null>  $query
181	     * @param  array<string, mixed>|null  $body
182	     * @return array<string, mixed>
183	     */
184	    public function request(
185	        Professional $professional,
186	        string $method,
187	        string $path,
188	        array $query = [],
189	        ?array $body = null
190	    ): array {
191	        $token = $this->tokenService->getAccessToken($professional);
192	        $attempt = 0;
193	        $maxRetries = 3;
194	
195	        while (true) {
196	            $response = $this->makeRequest($token, $method, $path, $query, $body);
197	
198	            if ($response->status() === 429 && $attempt < $maxRetries) {
199	                $wait = max(1000, ((int) ($response->header('Retry-After') ?? 1)) * 1000);
200	                usleep($wait * 1000);
201	                $attempt++;
202	
203	                continue;
204	            }
205	
206	            break;
207	        }
208	
209	        // Access token might have been revoked/expired unexpectedly; refresh once.
210	        if ($response->status() === 401) {
211	            $token = $this->tokenService->refreshAccessToken($professional);
212	            $response = $this->makeRequest($token, $method, $path, $query, $body);
213	        }
214	
215	        $payload = $response->json();
216	        if (! is_array($payload)) {
217	            $payload = [];
218	        }
219	
220	        if (! $response->successful()) {
221	            $status = $response->status();
222	            $message = sprintf('Fresha API request failed: %s %s (HTTP %s)', $method, $path, $status);
223	            $errors = is_array($payload['errors'] ?? null) ? $payload['errors'] : null;
224	            if (is_array($errors) && isset($errors[0]) && is_array($errors[0])) {
225	                $first = $errors[0];
226	                $detail = isset($first['detail']) && is_string($first['detail']) ? trim($first['detail']) : '';
227	                $code = isset($first['code']) && is_string($first['code']) ? trim($first['code']) : '';
228	
229	                $parts = [];
230	                if ($code !== '') {
231	                    $parts[] = $code;
232	                }
233	                $meta = $parts ? sprintf(' [%s]', implode('/', $parts)) : '';
234	                $suffix = $detail !== '' ? sprintf(': %s', $detail) : '';
235	                $message = sprintf('Fresha API %s %s failed (HTTP %s)%s%s', strtoupper($method), $path, $status, $meta, $suffix);
236	            }
237	
238	            throw new FreshaApiException($message, $status, $payload);
239	        }
240	
241	        return $payload;
242	    }
