244	    /**
245	     * @param  array<string, string|int|float|bool|null>  $query
246	     * @param  array<string, mixed>|null  $body
247	     */
248	    private function makeRequest(
249	        string $accessToken,
250	        string $method,
251	        string $path,
252	        array $query = [],
253	        ?array $body = null
254	    ): Response {
255	        $request = Http::acceptJson()
256	            ->asJson()
257	            ->timeout(30)
258	            ->withToken($accessToken);
259	
260	        $url = $this->baseUrl().$path;
261	
262	        return match (strtoupper($method)) {
263	            'GET' => $request->get($url, $query),
264	            'DELETE' => $request->delete($url, $query),
265	            'POST' => $request->post($url.($query ? '?'.http_build_query($query) : ''), $body ?? []),
266	            'PUT' => $request->put($url.($query ? '?'.http_build_query($query) : ''), $body ?? []),
267	            'PATCH' => $request->patch($url.($query ? '?'.http_build_query($query) : ''), $body ?? []),
268	            default => throw new FreshaApiException('Unsupported Fresha request method: '.$method),
269	        };
270	    }
271	
272	    private function baseUrl(): string
273	    {
274	        $environment = strtolower((string) config('services.fresha.environment', 'production'));
275	        if ($environment === 'sandbox') {
276	            return 'https://partner-api-sandbox.fresha.com';
277	        }
278	
279	        return 'https://partner-api.fresha.com';
280	    }
